def gen(rng):
    def fmt(a):
        return f"{len(a)}\n" + " ".join(map(str, a))
    tests = [fmt([7]), fmt([5, 5, 5, 5]), fmt([1, 2, 3, 4, 5]), fmt([-1, 1, -1, 0, 0, 1000000000, -1000000000, 1000000000]), fmt([3, 1, 3, 2, 1, 3])]
    for n in (2, 4, 7, 10, 15, 25, 40):
        for _ in range(2):
            v = rng.choice([2, 3, 5, 10, 30])
            tests.append(fmt([rng.randint(-v, v) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(100000)]))
    tests.append(fmt(list(range(100000, 0, -1))))
    tests.append(fmt([10**9] * 100000))
    return tests

